unsigned failures = 0;
#define CHECK(condition)                                                        \
    do {                                                                        \
        if (!(condition)) {                                                     \
            std::fprintf(stderr, "FAIL %d: %s\n", __LINE__, #condition);       \
            ++failures;                                                         \
        }                                                                       \
    } while (false)

bool drain_abandoned(replay::MetalReplayBackend& backend, std::uint64_t fence) {
    if (!fence) return false;
    static_cast<void>(backend.wait_fence(fence, 10'000'000'000ull));
    if (backend.fatal_error_detail().empty()) return false;
    return backend.stop_submission_workers(std::chrono::steady_clock::now() + std::chrono::seconds(5));
}

template <Entry E>
typename EntrySignature<E>::type load() {
    const auto loader = bootstrap_loader_for(selected_api_version().value_or(ApiVersion{55,15}));
    return reinterpret_cast<typename EntrySignature<E>::type>(loader(entry_name(E).data()));
}

// Synthetic fixtures declare their logical mesh route explicitly.
void bind_mesh_program(NVNcommandBuffer* commands, const NVNprogram* program, bool task) {
    load<Entry::nvnCommandBufferBindProgram>()(commands, program,
        (task ? 0xc0 : 0x80) | NVN_SHADER_STAGE_FRAGMENT_BIT);
    command_geometry_processing_mode(commands, task ? 1 : 2);
}

// ARMIGO_NVN_DISPATCH_PROFILE commits every dispatch on its own: no two
// dispatches share an encoder, so none skips a barrier.
bool dispatches_profiled() {
    const char* value = std::getenv("ARMIGO_NVN_DISPATCH_PROFILE");
    return value && *value == '1';
}

std::vector<std::byte> build_library(std::string_view source) {
    auto pattern = (std::filesystem::temp_directory_path() /
                    "armigo-nvn-replay-test-XXXXXX").string();
    std::vector<char> path(pattern.begin(), pattern.end());
    path.push_back('\0');
    if (!mkdtemp(path.data())) return {};
    const std::filesystem::path root(path.data());
    const auto source_path = root / "synthetic.metal";
    const auto air_path = root / "synthetic.air";
    const auto library_path = root / "synthetic.metallib";
    {
        std::ofstream output(source_path);
        output.write(source.data(), static_cast<std::streamsize>(source.size()));
    }
    const std::string compile = "xcrun --sdk macosx metal -c '" + source_path.string() +
        "' -o '" + air_path.string() + "'";
    const std::string link = "xcrun --sdk macosx metallib '" + air_path.string() +
        "' -o '" + library_path.string() + "'";
    if (std::system(compile.c_str()) || std::system(link.c_str())) return {};
    std::ifstream input(library_path, std::ios::binary);
    const std::string bytes{std::istreambuf_iterator<char>(input),
                            std::istreambuf_iterator<char>()};
    const auto span = std::as_bytes(std::span(bytes.data(), bytes.size()));
    std::vector<std::byte> result{span.begin(), span.end()};
    std::error_code ignored;
    std::filesystem::remove_all(root, ignored);
    return result;
}

