}
kernel void bits_image_compute(texture2d<uint, access::write> image [[texture(0)]]) {
    image.write(uint4(0xff00ff00u), uint2(0));
}
kernel void corner_image_compute(texture2d<float, access::write> image [[texture(0)]]) {
